INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_002_001", 1, 3000, 2, 1000, "vo_minigame_1013_icon_2_002_001", 2, 2, "調子が上がって\nきたなっ", "訓練はまだ\nここからですわ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_003_001", 2, 3000, 2, 5000, "vo_minigame_1013_icon_2_003_001", 2, 2, "ほらほら、\nまだいけるだろ？", "クスクス、悪くない\n流れですわね");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_004_001", 3, 3000, 2, 10000, "vo_minigame_1013_icon_2_004_001", 2, 3, "へへっ、おまえら\nやるじゃねえか！", "すばらしい\n記録ですわ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_005_001", 4, 3000, 2, 10000, "vo_minigame_1013_icon_2_005_001", 3, 3, "あたしたちはまだ\n止まらねえぜ！", "乗りに乗って\nいますわね");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_005_002", 5, 3000, 2, 10000, "vo_minigame_1013_icon_2_005_002", 3, 3, "見てろよ！\nマコト班の快進撃だ！", "まだまだ行きます\nついてきなさい");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_005_003", 6, 3000, 2, 10000, "vo_minigame_1013_icon_2_005_003", 3, 3, "うおぉぉっ！\n絶好調だぜ！", "エリコ班の\n本領発揮ですわ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_006_001", 7, 3000, 2, 0, "vo_minigame_1013_icon_2_006_001", 4, 3, "どこまで行けるか\n楽しみだなっ！", "ここからは\n前人未到の領域です！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_007_001", 8, 1000, 3, 1, "vo_minigame_1013_icon_2_007_001", 5, 4, "まだ諦めんなよっ", "厄介でしたわ…");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_007_002", 9, 1000, 3, 1, "vo_minigame_1013_icon_2_007_002", 5, 4, "冷やっとしたぜ…！", "油断大敵です");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_007_003", 10, 1000, 3, 1, "vo_minigame_1013_icon_2_007_003", 5, 4, "弱音を吐くなっ", "忌々しいっ…");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_008_001", 11, 1500, 4, 99, "vo_minigame_1013_icon_2_008_001", 6, 3, "マコト班集合！", "大所帯ですわね");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_008_002", 12, 1500, 4, 99, "vo_minigame_1013_icon_2_008_002", 6, 3, "連携してくぞ！", "エリコ班へようこそ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_020_001", 13, 3000, 1, 0, "vo_minigame_1013_icon_2_020_001", 8, 6, "みんなに力を！", "ナナカちゃんに\nお任せあれ");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_022_001", 14, 3000, 1, 0, "vo_minigame_1013_icon_2_022_001", 9, 7, "任せてくれたまえ", "はっはっは！\n任せろ！");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES ("vo_minigame_1013_icon_1_023_001", 15, 3000, 1, 0, "vo_minigame_1013_icon_2_023_001", 10, 8, "ほな、いきまひょか", "どんどんいくわよ");
